    // Environment files
    '.env',
    '.env.*',
    // Private keys and certificates
    '*.pem',
    '*.key',
    '*.p12',
    '*.pfx',
    '*.jks',
    '*.keystore',
    // SSH keys
    'id_rsa',
    'id_ed25519',
    'id_ecdsa',
    '*.pub',
